"use client";

/**
 * アプリの骨組み。どの画面もこの中に入る。
 *   767px 以下   … 下タブ（BottomTabBar）
 *   768〜1279px  … アイコン列（SideNav）
 *   1280px 以上  … サイドバー（SideNav・畳める）
 * どの画面からでも使うもの（追加・⌘K パレット・キーボードの近道）は、ここで1つだけ持つ。
 * アプリごとの中身（名前・追加シート・⌘K の候補・外側の入れ物）は config/shell.tsx から受け取る。このファイルは書き換えない。
 *
 * キーボードの近道（文字を入力中・シートやダイアログが開いている間は効かない）
 *   ⌘K / Ctrl+K / 「/」 … 検索・操作
 *   N                    … 追加（config/shell.tsx の AddSheet があるとき）
 *   1〜9                 … ナビの1〜9番目へ移動
 */
import { useRouter } from "next/navigation";
import { createContext, useContext, useEffect, useRef, useState } from "react";
import { NAV } from "@/config/nav";
import { AddSheet, ShellProviders } from "@/config/shell";
import { Toaster } from "@/components/kit/toast";
import { BottomTabBar } from "./bottom-tab-bar";
import { CommandPalette } from "./command-palette";
import { SideNav } from "./side-nav";
import { ThemeFonts } from "./theme-fonts";

const ShellCtx = createContext<{ openAdd: () => void; openSearch: () => void }>({ openAdd: () => {}, openSearch: () => {} });
export const useShell = () => useContext(ShellCtx);

const typing = (el: EventTarget | null) => el instanceof HTMLElement && (el.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName));
const overlayOpen = () => !!document.querySelector('[role="dialog"],[role="alertdialog"],[role="menu"]');

export function AppFrame({ children }: { children: React.ReactNode }) {
  const router = useRouter();
  const [adding, setAdding] = useState(false);
  const [searching, setSearching] = useState(false);
  const searchingRef = useRef(searching);
  useEffect(() => {
    searchingRef.current = searching;
  }, [searching]);
  const openAdd = () => setAdding(true);
  const openSearch = () => setSearching(true);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.isComposing) return;
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        // シートやメニューが開いている間は奪わない（重なって開き、打った文字が後ろのシートに入るため）。パレット自身を閉じるのは可
        if (!searchingRef.current && overlayOpen()) return;
        e.preventDefault();
        setSearching((s) => !s);
        return;
      }
      if (e.metaKey || e.ctrlKey || e.altKey || typing(e.target) || overlayOpen()) return;
      if (e.key === "/") {
        e.preventDefault();
        setSearching(true);
      } else if (AddSheet && (e.key === "n" || e.key === "N")) {
        e.preventDefault();
        setAdding(true);
      } else if (/^[1-9]$/.test(e.key) && NAV[Number(e.key) - 1]) {
        router.push(NAV[Number(e.key) - 1].href);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [router]);

  return (
    <ShellProviders>
      <ShellCtx.Provider value={{ openAdd, openSearch }}>
        <a href="#main" className="sr-only focus:not-sr-only focus:fixed focus:top-2 focus:left-2 focus:z-50 focus:rounded-md focus:bg-surface focus:px-3 focus:py-2">
          本文へ移動
        </a>
        <SideNav onAdd={AddSheet ? openAdd : undefined} onSearch={openSearch} />
        <div className="wk-content">
          <main id="main">{children}</main>
        </div>
        <BottomTabBar />
        {AddSheet && <AddSheet open={adding} onOpenChange={setAdding} />}
        <CommandPalette open={searching} onOpenChange={setSearching} onAdd={AddSheet ? openAdd : undefined} />
        <Toaster />
        <ThemeFonts />
      </ShellCtx.Provider>
    </ShellProviders>
  );
}

"use client";

/**
 * スマホの下タブ（767px 以下だけ表示）。動きは iOS 26 の標準的な下タブ（押した所へ光る丸が伸び縮みしながら移る）に合わせている。
 *
 *   指が触れた瞬間 … 押したタブのアイコンが選択表示になり、バー全体が 1.03 倍にふくらむ
 *   指を離した瞬間 … 画面を切り替える（中身はフェードも横すべりもしない＝即移動）
 *   選択の丸い板   … 約 180ms で次のタブへ滑る。速く動いている間だけ横に伸びて少し淡くなる。揺れ（行き過ぎ）は無し
 *   押さえたまま横になぞる … 板が指についてくる。離したところのタブへ移る
 *   動きを減らす設定 … 板は瞬間移動、ふくらみ無し
 *   項目が6つ以上（またはログイン中の人の欄がある）とき … 先頭4つ＋「もっと」。「もっと」は残りの項目とアカウント欄を下からのシートで出す
 *
 * 画面の切り替えは <Link> の先読み（App Shell）が効いているので、押してから待たない。
 * 今の場所（usePathname）は <Suspense> の中で読む。[id] のような動く住所の画面でも事前の描画が止まらないように、
 * 読めるまでは選択表示の無い同じバーを出す。
 */
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { animate, motion, useMotionValue, useReducedMotion, useTransform, useVelocity } from "motion/react";
import { Suspense, useCallback, useLayoutEffect, useRef, useState } from "react";
import { Ellipsis } from "lucide-react";
import { NAV, isActive } from "@/config/nav";
import { useAccount } from "@/config/shell";
import { Sheet } from "@/components/kit/sheet";
import { cn } from "@/lib/cn";

const SLIDE = { type: "spring", visualDuration: 0.18, bounce: 0 } as const;
const PRESS = { type: "spring", visualDuration: 0.12, bounce: 0 } as const;
const RELEASE = { type: "spring", visualDuration: 0.22, bounce: 0 } as const;
const INSET = 4; // 板とバーの縁のすき間
const DRAG_START = 6; // これ以上動いたら「なぞり」とみなす(px)

const MORE = { href: "#more", label: "もっと", short: "もっと", icon: Ellipsis };

export function BottomTabBar() {
  const account = useAccount();
  if (NAV.length === 0 && !account) return null;
  return (
    <Suspense fallback={<TabBar pathname={null} account={account} />}>
      <TabBarAtPath account={account} />
    </Suspense>
  );
}

function TabBarAtPath({ account }: { account: ReturnType<typeof useAccount> }) {
  return <TabBar pathname={usePathname()} account={account} />;
}

function TabBar({ pathname: at, account }: { pathname: string | null; account: ReturnType<typeof useAccount> }) {
  const pathname = at ?? "";
  const needsMore = NAV.length > 5 || !!account;
  const tabs = NAV.slice(0, needsMore ? 4 : 5);
  const rest = NAV.slice(tabs.length);
  const items = needsMore ? [...tabs, MORE] : tabs;
  const [moreOpen, setMoreOpen] = useState(false);
  const router = useRouter();
  const reduce = useReducedMotion();
  const barRef = useRef<HTMLElement>(null);
  const [width, setWidth] = useState(0);
  const slot = width / items.length;

  // 押した瞬間に選択表示にするための「仮の選択」。画面が移り終わったら実際の場所に従う
  // どのナビにも無い画面（と、場所がまだ分からない間）は -1＝どれも選ばない
  const tabIndex = at === null ? -1 : tabs.findIndex((i) => isActive(pathname, i.href));
  const routeIndex = tabIndex >= 0 ? tabIndex : at !== null && needsMore && rest.some((i) => isActive(pathname, i.href)) ? tabs.length : -1;
  const [pressed, setPressed] = useState<{ index: number; from: string } | null>(null);
  // 場所が変わったら（移り終わった・戻る/進む）仮の選択を捨てる
  const [seenPath, setSeenPath] = useState(pathname);
  if (seenPath !== pathname) {
    setSeenPath(pathname);
    setPressed(null);
  }
  const active = pressed && pressed.from === pathname ? pressed.index : routeIndex;

  const x = useMotionValue(0);
  const vx = useVelocity(x);
  // 隣のタブへ移るだけでも約1.2倍に伸びるよう、速さ 1200px/秒 で最大になる
  const stretch = useTransform(vx, [-1200, 0, 1200], [1.25, 1, 1.25], { clamp: true });
  const lensOpacity = useTransform(vx, [-1200, 0, 1200], [0.7, 1, 0.7], { clamp: true });
  const lens = useMotionValue(1); // なぞっている間だけ板を少し大きく
  const scaleX = useTransform(() => stretch.get() * lens.get());
  const scaleY = useTransform(() => (1 / Math.sqrt(stretch.get())) * lens.get());
  const barScale = useMotionValue(1);

  const drag = useRef<{ id: number; startX: number; start: number; dragging: boolean } | null>(null);
  const placed = useRef(false);

  useLayoutEffect(() => {
    const el = barRef.current;
    if (!el) return;
    const ro = new ResizeObserver(() => setWidth(el.clientWidth));
    ro.observe(el);
    setWidth(el.clientWidth);
    return () => ro.disconnect();
  }, []);

  const moveTo = useCallback(
    (index: number) => {
      if (!slot || index < 0) return;
      const to = index * slot;
      // 最初の配置と「動きを減らす」は瞬間移動
      if (!placed.current || reduce) {
        x.set(to);
        placed.current = true;
        return;
      }
      animate(x, to, SLIDE);
    },
    [slot, reduce, x],
  );

  useLayoutEffect(() => {
    if (!drag.current?.dragging) moveTo(active);
  }, [active, moveTo]);


  const indexAt = (clientX: number) => {
    const rect = barRef.current!.getBoundingClientRect();
    return Math.min(items.length - 1, Math.max(0, Math.floor(((clientX - rect.left) / rect.width) * items.length)));
  };

  const swell = (on: boolean) => {
    if (reduce) return;
    animate(barScale, on ? 1.03 : 1, on ? PRESS : RELEASE);
  };

  const go = (index: number) => {
    const href = items[index].href;
    if (href === MORE.href) {
      setPressed({ index, from: pathname });
      moveTo(index);
      setMoreOpen(true);
      return;
    }
    setPressed({ index, from: pathname });
    moveTo(index);
    if (!isActive(pathname, href)) router.push(href);
  };

  const onPointerDown = (e: React.PointerEvent<HTMLElement>) => {
    if (e.button !== 0 || !barRef.current) return;
    const index = indexAt(e.clientX);
    drag.current = { id: e.pointerId, startX: e.clientX, start: index, dragging: false };
    // 選択表示とふくらみは、指をつかむ処理より先に（つかめない端末でも押した瞬間に反応させる）
    setPressed({ index, from: pathname });
    swell(true);
    try {
      barRef.current.setPointerCapture(e.pointerId);
    } catch {}
  };

  const onPointerMove = (e: React.PointerEvent<HTMLElement>) => {
    const d = drag.current;
    if (!d || d.id !== e.pointerId || !barRef.current) return;
    if (!d.dragging && Math.abs(e.clientX - d.startX) < DRAG_START) return;
    if (!d.dragging) {
      d.dragging = true;
      if (!reduce) animate(lens, 1.1, PRESS);
    }
    const rect = barRef.current.getBoundingClientRect();
    const left = Math.min(width - slot, Math.max(0, e.clientX - rect.left - slot / 2));
    x.set(left);
    const index = indexAt(e.clientX);
    if (index !== active) setPressed({ index, from: pathname });
  };

  const finish = (e: React.PointerEvent<HTMLElement>, cancelled: boolean) => {
    const d = drag.current;
    if (!d || d.id !== e.pointerId) return;
    drag.current = null;
    swell(false);
    if (!reduce) animate(lens, 1, RELEASE);
    if (cancelled) {
      setPressed(null);
      moveTo(routeIndex);
      return;
    }
    go(d.dragging ? indexAt(e.clientX) : d.start);
  };

  return (
    <>
    <nav
      ref={barRef}
      aria-label="メインメニュー"
      data-nav="tabbar"
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={(e) => finish(e, false)}
      onPointerCancel={(e) => finish(e, true)}
      className="fixed inset-x-3 z-40 mx-auto flex max-w-[520px] touch-none select-none rail:hidden"
      style={{
        bottom: "calc(var(--wk-tabbar-gap) + var(--wk-safe-b))",
        height: "var(--wk-tabbar-h)",
      }}
    >
      <motion.div
        aria-hidden
        className="wk-glass-bar absolute inset-0 rounded-full border border-[var(--wk-glass-line)] bg-[var(--wk-glass)] shadow-[inset_0_1px_0_var(--wk-glass-hi),var(--wk-shadow)] backdrop-blur-[18px] backdrop-saturate-[1.8]"
        style={{ scale: barScale }}
      />
      <motion.div
        aria-hidden
        className="pointer-events-none absolute rounded-full bg-[color-mix(in_oklab,var(--wk-fg)_9%,transparent)]"
        style={{
          top: INSET,
          bottom: INSET,
          left: INSET,
          width: Math.max(0, slot - INSET * 2),
          x,
          // 動きを減らす設定では伸び縮みを付けない（瞬間移動の一瞬に速さが跳ねて伸びるため）。
          // 設定の有無で style の項目を変えるとサーバーとの水和が食い違うので、項目は常に同じにして値だけ変える
          scaleX: reduce ? 1 : scaleX,
          scaleY: reduce ? 1 : scaleY,
          opacity: active < 0 ? 0 : reduce ? 1 : lensOpacity,
        }}
      />
      {items.map((item, i) => {
        const on = i === active;
        const Icon = item.icon;
        const cls = cn(
          "relative z-10 flex min-w-11 flex-1 flex-col items-center justify-center gap-0.5 rounded-full text-xs",
          "transition-colors duration-[var(--wk-dur-fast)]",
          on ? "text-fg" : "text-fg-3",
        );
        const inner = (
          <>
            <Icon aria-hidden size={22} strokeWidth={on ? 2.4 : 1.8} />
            <span className={cn("leading-none", on && "font-medium")}>{item.short}</span>
          </>
        );
        if (item.href === MORE.href) {
          return (
            <button
              key={item.href}
              type="button"
              aria-haspopup="dialog"
              aria-expanded={moreOpen}
              aria-current={i === routeIndex && tabIndex < 0 ? "page" : undefined}
              // 指やマウスは上の pointer の処理で開く。キーボード（Enter・Space）のときだけここで開く
              onClick={(e) => {
                if (e.detail === 0) go(i);
              }}
              className={cls}
            >
              {inner}
            </button>
          );
        }
        return (
          <Link
            key={item.href}
            href={item.href}
            aria-current={isActive(pathname, item.href) ? "page" : undefined}
            // 指やマウスでの移動は上の pointer の処理で行う。キーボード（Enter）のときだけ通常どおり移動する
            onClick={(e) => {
              if (e.detail !== 0) e.preventDefault();
            }}
            draggable={false}
            className={cls}
          >
            {inner}
          </Link>
        );
      })}
    </nav>
    {needsMore && (
      <Sheet
        open={moreOpen}
        onOpenChange={(open) => {
          setMoreOpen(open);
          // 何も選ばずに閉じたら、板を今いる場所へ戻す
          if (!open) setPressed(null);
        }}
        title="メニュー"
      >
        <MoreList
          rest={rest}
          pathname={pathname}
          account={account}
          onPick={(run, navigates) => {
            setMoreOpen(false);
            // 画面が移らない操作（ログアウト前の確認・明るさの切り替えなど）は、板を今いる場所へ戻す
            if (!navigates) setPressed(null);
            run();
          }}
        />
      </Sheet>
    )}
    </>
  );
}

/** 「もっと」の中身：下タブに入らなかった項目と、ログイン中の人の欄 */
function MoreList({
  rest,
  pathname,
  account,
  onPick,
}: {
  rest: typeof NAV;
  pathname: string;
  account: ReturnType<typeof useAccount>;
  onPick: (run: () => void, navigates: boolean) => void;
}) {
  const router = useRouter();
  const row = "flex min-h-row w-full items-center gap-3 rounded-md px-3 text-left transition-colors active:bg-surface-2";
  return (
    <div className="grid gap-4">
      {rest.length > 0 && (
        <ul className="grid gap-0.5">
          {rest.map((item) => {
            const on = isActive(pathname, item.href);
            const Icon = item.icon;
            return (
              <li key={item.href}>
                <Link
                  href={item.href}
                  aria-current={on ? "page" : undefined}
                  onClick={(e) => {
                    e.preventDefault();
                    onPick(() => router.push(item.href), true);
                  }}
                  className={cn(row, on ? "bg-accent-soft font-medium text-accent-text" : "text-fg hover:bg-surface-2")}
                >
                  <Icon aria-hidden size={20} className="flex-none text-current" />
                  {item.label}
                </Link>
              </li>
            );
          })}
        </ul>
      )}
      {account && (
        <div className="grid gap-0.5 border-t border-line pt-3">
          <p className="truncate px-3 pb-1 text-sm text-fg-3">{account.name}</p>
          {account.actions.map((a) => (
            <button key={a.id} type="button" onClick={() => onPick(a.run, false)} className={cn(row, "text-fg hover:bg-surface-2")}>
              <a.icon aria-hidden size={20} className="flex-none" />
              {a.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/*
 * テーマ・明るさ・密度・サイドバーの開閉を、描画の前に <html> へ反映する（ちらつき防止）。
 * 保存先はこのブラウザだけ（localStorage）。読めなくても既定値で正しく表示される。
 * テーマの優先順：URL の ?palette=…（見本サイトの並べ比べ用。覚えさせない）→ この端末で選んだテーマ → アプリの既定テーマ
 */
import { PALETTES } from "@/lib/palettes";

/** 常に暗い専用のテーマ。明るさをライトに固定したアプリでは選ばせない */
const DARK_ONLY = PALETTES.filter((p) => p.darkOnly).map((p) => p.id);

export function bootScript(defaultPalette = "graphite", forceTheme?: "light" | "dark") {
  const def = JSON.stringify(/^[a-z0-9-]+$/.test(defaultPalette) ? defaultPalette : "graphite");
  // 明るさを固定するアプリ（ダーク未対応の画面が残っている後付けなど）は、保存された明るさより優先し、切り替えの操作も隠す
  const lock =
    forceTheme === "light" || forceTheme === "dark"
      ? `d.dataset.theme="${forceTheme}";d.dataset.themeLocked="1";` +
        (forceTheme === "light" ? `if(${JSON.stringify(DARK_ONLY)}.indexOf(d.dataset.palette)>=0)delete d.dataset.palette;` : "")
      : "";
  return `try{var d=document.documentElement,q=new URLSearchParams(location.search),v=${def},p=q.get("palette"),ok=/^[a-z0-9-]+$/;try{var x=localStorage.getItem("wk.palette");if(x&&ok.test(x))v=x}catch(e){}if(p&&ok.test(p))v=p;if(v!=="graphite")d.dataset.palette=v;var m=q.get("theme");if(m==="light"||m==="dark")d.dataset.theme=m;${lock}}catch(e){}try{var d=document.documentElement,s=localStorage;var t=s.getItem("wk.theme");if(!d.dataset.theme&&(t==="light"||t==="dark"))d.dataset.theme=t;var n=s.getItem("wk.density");if(n==="compact")d.dataset.density=n;if(s.getItem("wk.sidebar")==="collapsed")d.dataset.sidebar="collapsed"}catch(e){}`;
}

/**
 * ルートの layout の <head> の中に置く。既存のアプリに入れるときも、これを1行足すだけでよい。
 * defaultPalette … このアプリの既定のテーマ（例："sky"）。使う人が設定や ⌘K で選ぶと、その端末ではそちらが優先される
 * forceTheme     … 明るさを固定する（"light" か "dark"）。ダーク表示に対応していない画面が残っているうちに使う
 */
export function WorkspaceBoot({ defaultPalette = "graphite", forceTheme }: { defaultPalette?: string; forceTheme?: "light" | "dark" }) {
  return <script dangerouslySetInnerHTML={{ __html: bootScript(defaultPalette, forceTheme) }} />;
}

"use client";

/**
 * ⌘K パレット（検索と操作の入口）。⌘K / Ctrl+K・「/」・サイドバーの「検索・操作」・一覧の「検索」で開く。
 *   文字を打つと、操作とアプリの中身（config/shell.tsx の useExtraCommands）を同時に絞り込む。↑↓ で選んで Enter、esc で閉じる。
 * 操作を増やすときは commands の配列に、アプリの中身は useExtraCommands に足す（group が見出しになる）。
 */
import { Dialog } from "@base-ui/react/dialog";
import { CornerDownLeft, Monitor, Moon, Palette, Plus, Rows3, Search, Sun, type LucideIcon } from "lucide-react";
import { useRouter } from "next/navigation";
import { useId, useState } from "react";
import { NAV } from "@/config/nav";
import { PALETTES } from "@/lib/palettes";
import { setDensity, setPalette, setTheme, themeLocked } from "@/lib/prefs";
import { APP, AddSheet, useAccount, useExtraCommands } from "@/config/shell";
import { cn } from "@/lib/cn";

/** ナビの一番下（スマホは「もっと」の中）と ⌘K に出す、ログイン中の人と操作 */
export type AccountInfo = { name: string; actions: { id: string; label: string; icon: LucideIcon; run: () => void }[] };

export type PaletteItem = { id: string; group: string; label: string; hint?: string; icon: LucideIcon; keywords?: string; run: () => void };

export function CommandPalette({ open, onOpenChange, onAdd }: { open: boolean; onOpenChange: (open: boolean) => void; onAdd?: () => void }) {
  return (
    <Dialog.Root open={open} onOpenChange={onOpenChange}>
      <Dialog.Portal>
        {/* 出し入れの動きは付けない。キーボードで1日に何十回も開くので、押した瞬間に出て、すぐ消える方が速く感じる */}
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-scrim" />
        <Dialog.Popup className="fixed top-[max(12px,env(safe-area-inset-top,0px))] left-1/2 z-50 flex max-h-[min(560px,calc(100dvh-24px))] w-[min(600px,calc(100vw-24px))] -translate-x-1/2 flex-col overflow-hidden rounded-lg border border-line bg-surface shadow-float outline-none rail:top-[12vh]">
          <Dialog.Title className="sr-only">検索・操作</Dialog.Title>
          <Body
            onRun={(run) => {
              onOpenChange(false);
              // 閉じてから実行する（次に開くシートとフォーカスを取り合わないように）
              setTimeout(run, 0);
            }}
            onAdd={onAdd}
          />
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

function Body({ onRun, onAdd }: { onRun: (run: () => void) => void; onAdd?: () => void }) {
  const router = useRouter();
  const [q, setQ] = useState("");
  const needle = q.trim().toLowerCase();
  const extra = useExtraCommands(needle);
  const account = useAccount();
  const [active, setActive] = useState(0);
  const listId = useId();

  const commands: PaletteItem[] = [
    ...(AddSheet && onAdd ? [{ id: "add", group: "操作", label: APP.addLabel, hint: "N", icon: Plus, keywords: "新規 つくる 追加", run: onAdd }] : []),
    ...NAV.map((n, i) => ({ id: `go-${n.href}`, group: "移動", label: `${n.label}を開く`, hint: String(i + 1), icon: n.icon, run: () => router.push(n.href) })),
    // 明るさを固定しているアプリ（WorkspaceBoot の forceTheme）では、明るさの切り替えを出さない
    ...(themeLocked() ? [] : [
    { id: "light", group: "見た目", label: "明るさ：ライト", icon: Sun, keywords: "テーマ 白", run: () => setTheme("light") },
    { id: "dark", group: "見た目", label: "明るさ：ダーク", icon: Moon, keywords: "テーマ 黒 夜", run: () => setTheme("dark") },
    { id: "system", group: "見た目", label: "明るさ：端末に合わせる", icon: Monitor, keywords: "テーマ 自動", run: () => setTheme("system") },
    ]),
    { id: "compact", group: "見た目", label: "行の高さ：詰める", icon: Rows3, keywords: "密度", run: () => setDensity("compact") },
    { id: "comfy", group: "見た目", label: "行の高さ：ゆったり", icon: Rows3, keywords: "密度", run: () => setDensity("comfy") },
    ...(account?.actions.map((a) => ({ id: `account-${a.id}`, group: "アカウント", label: a.label, hint: account.name, icon: a.icon, run: a.run })) ?? []),
    // 明るさを固定しているときは、常に暗い専用のテーマ（ナイトなど）を出さない
    ...PALETTES.filter((p) => !(p.darkOnly && themeLocked())).map((p) => ({ id: `palette-${p.id}`, group: "テーマ", label: `テーマ：${p.label}`, icon: Palette, keywords: `色 ${p.desc}`, run: () => setPalette(p.id) })),
  ];

  const hit = (s: string) => s.toLowerCase().includes(needle);
  const items = [...commands.filter((c) => !needle || hit(c.label) || hit(c.keywords ?? "")), ...extra];
  const cur = Math.min(active, Math.max(0, items.length - 1));
  const optionId = (i: number) => `${listId}-${i}`;

  const groups: { name: string; rows: { item: PaletteItem; index: number }[] }[] = [];
  items.forEach((item, index) => {
    const g = groups.find((x) => x.name === item.group) ?? groups[groups.push({ name: item.group, rows: [] }) - 1];
    g.rows.push({ item, index });
  });

  return (
    <>
      <div className="flex flex-none items-center gap-2.5 border-b border-line px-4">
        <Search aria-hidden size={18} className="flex-none text-fg-3" />
        <input
          autoFocus
          role="combobox"
          aria-expanded="true"
          aria-controls={listId}
          aria-activedescendant={items.length ? optionId(cur) : undefined}
          aria-label={APP.searchLabel}
          placeholder={APP.searchLabel}
          value={q}
          onChange={(e) => {
            setQ(e.target.value);
            setActive(0);
          }}
          onKeyDown={(e) => {
            if (e.nativeEvent.isComposing) return;
            if (e.key === "ArrowDown" || e.key === "ArrowUp") {
              e.preventDefault();
              const n = items.length;
              if (n) setActive((cur + (e.key === "ArrowDown" ? 1 : n - 1)) % n);
            } else if (e.key === "Enter" && items[cur]) {
              e.preventDefault();
              onRun(items[cur].run);
            }
          }}
          className="h-14 min-w-0 flex-1 bg-transparent outline-none placeholder:text-fg-3 focus-visible:outline-none"
          autoComplete="off"
          enterKeyHint="go"
        />
        <Dialog.Close className="h-hit flex-none rounded-sm px-2 text-xs text-fg-3 hover:bg-surface-2 hover:text-fg">
          <span className="pointer-coarse:hidden">esc</span>
          <span className="hidden pointer-coarse:inline">閉じる</span>
        </Dialog.Close>
      </div>

      <div id={listId} role="listbox" aria-label="候補" className="min-h-0 flex-1 overflow-y-auto overscroll-contain p-1.5">
        {items.length ? (
          groups.map((g) => (
            <div key={g.name} role="group" aria-label={g.name}>
              <div aria-hidden className="px-2.5 pt-2.5 pb-1 text-xs text-fg-3">
                {g.name}
              </div>
              {g.rows.map(({ item, index }) => (
                <div
                  key={item.id}
                  id={optionId(index)}
                  role="option"
                  aria-selected={index === cur}
                  onPointerMove={() => index !== cur && setActive(index)}
                  onClick={() => onRun(item.run)}
                  // 選んでいる行は、地の色に加えて左に主色の線を出す（地の色の差だけでは見分けにくい）
                  className={cn("flex min-h-hit cursor-pointer items-center gap-3 rounded-md px-2.5 py-1.5 text-sm", index === cur && "bg-surface-2 shadow-[inset_2px_0_0_var(--wk-accent)]")}
                >
                  <item.icon aria-hidden size={16} className="flex-none text-fg-3" />
                  <span className="min-w-0 flex-1 truncate">{item.label}</span>
                  {item.hint && <span className="flex-none text-xs text-fg-3">{item.hint}</span>}
                  {index === cur && <CornerDownLeft aria-hidden size={14} className="flex-none text-fg-3 pointer-coarse:hidden" />}
                </div>
              ))}
            </div>
          ))
        ) : (
          <p className="px-3 py-8 text-center text-sm text-fg-3">「{q}」に合うものはありません</p>
        )}
      </div>

      <div aria-hidden className="flex flex-none gap-4 border-t border-line px-4 py-2 text-xs text-fg-3 pointer-coarse:hidden">
        <span>↑↓ 選ぶ</span>
        <span>Enter 実行</span>
        <span>esc 閉じる</span>
      </div>
    </>
  );
}

"use client";

/**
 * PC・タブレットのナビ。768〜1279px はアイコン列、1280px 以上はサイドバー（畳むとアイコン列）。
 * 項目と順番は下タブと同じ（config/nav.ts）。押した瞬間に選択表示を移し、画面の切り替えは待たせない。
 * 画面の切り替えは1日に何十回もするので、選択の下地は動かさずにその場で入れ替える。
 * 今の場所（usePathname）は <Suspense> の中で読む（動く住所の画面でも事前の描画を止めない）。読めるまでは選択表示の無い同じナビを出す。
 * 項目が多いときは、項目の部分だけが縦にスクロールする（項目を押しつぶさない）。
 */
import Link from "next/link";
import { usePathname } from "next/navigation";
import { PanelLeftClose, PanelLeftOpen, Plus, Search } from "lucide-react";
import { Suspense, useState } from "react";
import { NAV, isActive } from "@/config/nav";
import { APP, useAccount } from "@/config/shell";
import { cn } from "@/lib/cn";

function setCollapsed(collapsed: boolean) {
  const d = document.documentElement;
  if (collapsed) d.dataset.sidebar = "collapsed";
  else delete d.dataset.sidebar;
  try {
    localStorage.setItem("wk.sidebar", collapsed ? "collapsed" : "open");
  } catch {}
}

const itemClass =
  "flex h-11 w-full flex-none items-center gap-3 rounded-md px-3 text-sm whitespace-nowrap transition-colors duration-[var(--wk-dur-fast)] " +
  "max-side:justify-center max-side:px-0 [:root[data-sidebar=collapsed]_&]:justify-center [:root[data-sidebar=collapsed]_&]:px-0";

type Props = { onSearch?: () => void; onAdd?: () => void };

export function SideNav(props: Props) {
  return (
    <Suspense fallback={<Side {...props} pathname={null} />}>
      <SideAtPath {...props} />
    </Suspense>
  );
}

function SideAtPath(props: Props) {
  return <Side {...props} pathname={usePathname()} />;
}

function Side({ onSearch, onAdd, pathname: at }: Props & { pathname: string | null }) {
  const pathname = at ?? "";
  const account = useAccount();
  const [pressed, setPressed] = useState<{ href: string; from: string } | null>(null);
  const [seenPath, setSeenPath] = useState(pathname);
  if (seenPath !== pathname) {
    setSeenPath(pathname);
    setPressed(null);
  }
  const current = pressed && pressed.from === pathname ? pressed.href : null;

  return (
    <nav
      aria-label="メインメニュー"
      data-nav="side"
      className="fixed inset-y-0 left-0 z-30 hidden flex-col gap-1 overflow-hidden border-r border-line bg-sidebar py-4 pr-3 rail:flex"
      style={{
        width: "var(--wk-nav-w)",
        // 横向きの iPhone では切り欠きの分だけ内側に寄せる
        paddingLeft: "max(0.75rem, env(safe-area-inset-left, 0px))",
        // 幅は動かさない（width を動かすと本文の配置計算が毎コマ走り、窓幅を変えたときも本文が遅れてついてくる）
      }}
    >
      <div className="mb-3 flex items-center gap-2.5 px-1.5 max-side:justify-center max-side:px-0 [:root[data-sidebar=collapsed]_&]:justify-center [:root[data-sidebar=collapsed]_&]:px-0">
        <span className="grid size-8 flex-none place-items-center rounded-lg bg-accent text-sm font-semibold text-on-accent">{APP.mark}</span>
        <span className="wk-nav-label truncate text-sm font-semibold">{APP.name}</span>
      </div>

      {onSearch && (
        <button type="button" onClick={onSearch} title="検索・操作（⌘K）" className={cn(itemClass, "mb-2 border border-line bg-surface text-fg-2 hover:text-fg active:bg-surface-2")}>
          <Search aria-hidden size={18} className="flex-none" />
          <span className="wk-nav-label">検索・操作</span>
          <kbd className="wk-nav-label ml-auto rounded border border-line px-1.5 font-sans text-xs text-fg-3">⌘K</kbd>
        </button>
      )}

      <div className="-mx-1 grid min-h-0 flex-1 content-start gap-1 overflow-y-auto px-1">
      {NAV.map((item) => {
        const on = current ? current === item.href : at !== null && isActive(pathname, item.href);
        const Icon = item.icon;
        return (
          <Link
            key={item.href}
            href={item.href}
            title={item.label}
            aria-current={at !== null && isActive(pathname, item.href) ? "page" : undefined}
            onPointerDown={(e) => {
              // 右クリック・新しいタブで開く（⌘・Ctrl・Shift）は、この画面の選択を変えない
              if (e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
              setPressed({ href: item.href, from: pathname });
            }}
            // 押したまま外へずらして離したら、仮の選択を捨てる
            onPointerCancel={() => setPressed(null)}
            onPointerLeave={(e) => {
              if (e.buttons) setPressed(null);
            }}
            className={cn(itemClass, on ? "bg-accent-soft font-medium text-accent-text" : "text-fg-2 hover:bg-surface-2 hover:text-fg")}
          >
            <Icon aria-hidden size={20} strokeWidth={on ? 2.2 : 1.8} className="flex-none" />
            <span className="wk-nav-label">{item.label}</span>
          </Link>
        );
      })}
      </div>

      {onAdd && (
        <button type="button" onClick={onAdd} title={APP.addLabel} className={cn(itemClass, "text-fg-2 hover:bg-surface-2 hover:text-fg active:bg-surface-2")}>
          <Plus aria-hidden size={20} className="flex-none" />
          <span className="wk-nav-label">{APP.addLabel}</span>
        </button>
      )}
      {account && (
        <div className="mt-1 grid gap-1 border-t border-line pt-2">
          <p className="wk-nav-wide px-3 text-xs text-fg-3" title={account.name}>
            <span className="min-w-0 truncate">{account.name}</span>
          </p>
          {account.actions.map((a) => (
            <button key={a.id} type="button" onClick={a.run} title={a.label} className={cn(itemClass, "text-fg-2 hover:bg-surface-2 hover:text-fg active:bg-surface-2")}>
              <a.icon aria-hidden size={20} className="flex-none" />
              <span className="wk-nav-label">{a.label}</span>
            </button>
          ))}
        </div>
      )}
      {/* 畳む・広げる（1280px 以上のときだけ） */}
      <button
        type="button"
        onClick={() => setCollapsed(document.documentElement.dataset.sidebar !== "collapsed")}
        className={cn(itemClass, "hidden text-fg-3 hover:bg-surface-2 hover:text-fg side:flex")}
        title="サイドバーを畳む・広げる"
      >
        <PanelLeftClose aria-hidden size={20} className="flex-none [:root[data-sidebar=collapsed]_&]:hidden" />
        <PanelLeftOpen aria-hidden size={20} className="hidden flex-none [:root[data-sidebar=collapsed]_&]:block" />
        <span className="wk-nav-label">畳む</span>
      </button>
    </nav>
  );
}

"use client";

/**
 * 選んだテーマのフォントを Google Fonts から読み込む（グラファイトは next/font で読み込み済みなので何もしない）。
 * 届くまでは端末の日本語フォントで表示され、届いたら差し替わる。
 */
import { PALETTES } from "@/lib/palettes";
import { usePalette } from "@/lib/prefs";

export function ThemeFonts() {
  const id = usePalette();
  const p = id === "graphite" ? null : PALETTES.find((x) => x.id === id);
  return p ? <link rel="stylesheet" href={p.href} /> : null;
}

import { House, Settings2, type LucideIcon } from "lucide-react";

/**
 * 画面の切り替え（ナビ）の項目。ここを書き換えると、サイドバー・アイコン列・下タブの全部が同じ順番で変わる。
 * - label: サイドバーに出す名前
 * - short: 下タブに出す短い名前（全角4文字まで）
 * - 下タブに出るのは先頭5つまで。6つ以上か config/shell.tsx の useAccount があるときは、先頭4つ＋「もっと」（残りは中のシート）
 */
export type NavItem = { href: string; label: string; short: string; icon: LucideIcon };

export const NAV: NavItem[] = [
  { href: "/", label: "ホーム", short: "ホーム", icon: House },
  { href: "/settings", label: "設定", short: "設定", icon: Settings2 },
];

/** 今の場所がその項目の中か（"/" は完全一致、それ以外は配下も含む） */
export function isActive(pathname: string, href: string) {
  return href === "/" ? pathname === "/" : pathname === href || pathname.startsWith(href + "/");
}

"use client";

/**
 * 骨組み（ナビ・⌘K パレット・追加ボタン）と、このアプリの中身をつなぐ場所。
 * 骨組み（components/shell/）は触らず、アプリごとに変えるのはこのファイルと config/nav.ts だけにする。
 *
 * - APP           … サイドバーの左上に出す名前と頭文字、追加ボタンと ⌘K の入力欄の文言
 * - ShellProviders … 骨組みの外側で包みたい物（データの入れ物など）。無ければ children をそのまま返す
 * - AddSheet      … 「追加」ボタン・N キー・⌘K の「追加」で開くシート。追加が無いアプリは null のまま
 * - useExtraCommands … ⌘K パレットに足す候補（打った文字で絞り込む）。無ければ空の配列を返す
 * - useAccount   … ナビの一番下に出す「ログイン中の人」と操作（ログアウトなど）。無ければ null。スマホでは下タブの「もっと」の中に出る
 */
import type { AccountInfo, PaletteItem } from "@/components/shell/command-palette";

export const APP = {
  name: "My App",
  mark: "M",
  addLabel: "追加",
  searchLabel: "探す・操作を選ぶ",
};

export function ShellProviders({ children }: { children: React.ReactNode }) {
  return <>{children}</>;
}

export const AddSheet: React.ComponentType<{ open: boolean; onOpenChange: (open: boolean) => void }> | null = null;

/** needle … 打った文字（小文字・前後の空白なし）。空のときは「よく使う物」を少しだけ返す */
// eslint-disable-next-line @typescript-eslint/no-unused-vars
export function useExtraCommands(needle: string): PaletteItem[] {
  return [];
}

/** ログインのあるアプリは、ここでログイン中の人の名前（メールなど）と操作を返す */
export function useAccount(): AccountInfo | null {
  return null;
}
